const articles = [];
for (const item of $input.all()) {
  if (item.json.title) {
    articles.push({
      title: item.json.title,
      summary: item.json.contentSnippet || item.json.summary || '',
      link: item.json.link || '',
      source: 'AI News'
    });
  }
}
return articles.slice(0, 5).map(article => ({ json: article }));

const inputData = $input.first().json;
const date = new Date().toLocaleDateString('en-US', { 
  weekday: 'long', 
  year: 'numeric', 
  month: 'long', 
  day: 'numeric' 
});

let content = 'Content unavailable';

// Extract content (existing logic)
if (inputData?.choices && Array.isArray(inputData.choices) && inputData.choices.length > 0) {
  content = inputData.choices[0].message?.content || inputData.choices[0].text || 'No content in choices[0]';
} else if (inputData?.message?.content) {
  content = inputData.message.content;
} else if (inputData?.content) {
  content = inputData.content;
} else if (inputData?.text) {
  content = inputData.text;
} else if (typeof inputData === 'string') {
  content = inputData;
} else {
  content = `Received data structure: ${JSON.stringify(inputData, null, 2)}`;
}

// Helper that splits the raw output into structured sections
function formatContent(rawContent) {
  // Split into sections based on the leading numbering
  const sections = rawContent.split(/(?=\d+\.\s\*\*)/);
  let formattedSections = '';

  sections.forEach(section => {
    if (section.trim()) {
      // Extract the title and the body of each section
      const lines = section.trim().split('\n');
      const titleLine = lines[0];
      const contentLines = lines.slice(1).join(' ').trim();

      if (titleLine.includes('**')) {
        const title = titleLine.replace(/^\d+\.\s/, '').replace(/\*\*/g, '');
        formattedSections += `
          <div style="margin-bottom: 25px; padding: 20px; background: #f8f9fa; border-left: 4px solid #007bff; border-radius: 8px;">
            <h3 style="color: #007bff; margin: 0 0 10px 0; font-size: 18px;">${title}</h3>
            <p style="margin: 0; line-height: 1.6; color: #333;">${contentLines}</p>
          </div>
        `;
      }
    }
  });

  return formattedSections;
}

const formattedContent = formatContent(content);

const html = `
<!DOCTYPE html>
<html>
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>AI Newsletter</title>
</head>
<body style="margin: 0; padding: 0; font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif; background-color: #f4f4f4;">
  <div style="max-width: 600px; margin: 0 auto; background-color: white; box-shadow: 0 4px 6px rgba(0,0,0,0.1);">

    <!-- Header -->
    <div style="background: linear-gradient(135deg, #667eea 0%, #764ba2 100%); padding: 30px 20px; text-align: center;">
      <h1 style="color: white; margin: 0; font-size: 28px; font-weight: 300; letter-spacing: 1px;">
        🤖 AI Newsletter
      </h1>
      <p style="color: rgba(255,255,255,0.9); margin: 10px 0 0 0; font-size: 16px;">
        ${date}
      </p>
    </div>

    <!-- Content -->
    <div style="padding: 30px 20px;">
      <div style="margin-bottom: 25px;">
        <h2 style="color: #333; font-size: 22px; margin: 0 0 15px 0; border-bottom: 2px solid #eee; padding-bottom: 10px;">
          📈 Latest AI News Roundup
        </h2>
      </div>

      ${formattedContent}

      <!-- Footer info -->
      <div style="margin-top: 30px; padding: 20px; background: #f8f9fa; border-radius: 8px; text-align: center;">
        <p style="margin: 0; color: #666; font-size: 14px;">
          💡 <em>Questions or feedback? Reply to this email and ask for more details on any topic.</em>
        </p>
      </div>
    </div>

    <!-- Footer -->
    <div style="background: #333; padding: 20px; text-align: center;">
      <p style="color: #ccc; margin: 0; font-size: 12px;">
        Newsletter generated automatically • ${new Date().getFullYear()}
      </p>
    </div>

  </div>
</body>
</html>
`;

return [{
  json: {
    html: html,
    subject: `🤖 AI Newsletter - ${date}`
  }
}];

return items.filter(
  item =>
    (item.json.title && /artificial intelligence|ai|machine learning/i.test(item.json.title)) ||
    (item.json.description && /artificial intelligence|ai|machine learning/i.test(item.json.description))
);
